    foreach (baselineProductionRoots($root) as $directory => $namespace) {
60→        $files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/'.$directory, FilesystemIterator::SKIP_DOTS));

        foreach ($files as $file) {
            if (! $file instanceof SplFileInfo || $file->getExtension() !== 'php') {
                continue;
            }
            $class = $namespace.str_replace('/', '\\', substr($file->getPathname(), strlen($root.'/'.$directory) + 1, -4));

            if (! class_exists($class) && ! enum_exists($class)) {
                continue;
70→            }
            $reflection = new ReflectionClass($class);
            $kinds = array_keys(array_filter([
                'enum' => $reflection->isEnum(),
